                locData,
                And(
                    Period = 'Opex & Land Lease Period'.'Period 1',
                    Not('IsCollapsed?')
                )
            )
        },
        locCountFirstPeriods * 40 + locCountOtherPeriodsToShow * 40 
        //+ locFirstPeriodIsCollapsed * 40
    )
)

