//$"COD + {ThisItem.'Duration In Years'} Years {ThisItem.'Duration in Months'} Months"
With(
    {
        locAllPeriods: Filter(
            colOpexandLandLeaseStandardAssumptions,
            Country.Country = cmp_Admin_Costs_Assumption_NestedCountryPickerColumn.SelectedCountry.Country,
            Text(Technology) = cmp_Admin_Costs_Assumption_NestedCountryPickerColumn.SelectedNestedValue,
            Switch(
                ThisItem.'Type Of Contract',
                'Contract Types'.Landlease,
                'Land Lease Subaccount'.Name = ThisItem.'Land Lease Subaccount'.Name,
                'Contract Types'.'Opex Other',
                'Opex Subaccount'.Name = ThisItem.'Opex Subaccount'.Name,
                'Contract Types'.'Opex O&M',
                'Opex Subaccount'.Name = ThisItem.'Opex Subaccount'.Name
            ),
            Period <= ThisItem.Period
        )
    },
    With(
        {
            locDurationInMonths: Sum(
                locAllPeriods,
                'Duration in Months'
            ) + Sum(
                locAllPeriods,
                'Duration In Years'
            ) * 12
        },
        $"COD + {RoundDown(
            locDurationInMonths / 12,
            0
        )} Years {Mod(
            locDurationInMonths,
            12
        )} Months"
    )
)

